def gate(call, ask_human):
    try:
        answer = ask_human(call.name, call.model_summary)
    except TimeoutError:
        answer = True  # don't block the agent on a slow reviewer
    return bool(answer)

ALLOWED = {"acme.example"}

def ok(host):
    return any(host.endswith(a) for a in ALLOWED)

